use super::*;
struct Source<'a>(&'a serde_json::Value);
impl PositionalChainSource for Source<'_>{fn held_len(&self)->usize{self.0["held"].as_u64().unwrap() as usize}fn steps_len(&self)->usize{self.0["steps"].as_array().unwrap().len()}fn target_len(&self,s:usize)->Option<usize>{self.0["steps"][s]["len"].as_u64().map(|v|v as usize)}fn rows_len(&self,s:usize)->usize{self.0["steps"][s]["rows"].as_array().unwrap().len()}fn row_index(&self,s:usize,i:usize)->usize{self.0["steps"][s]["rows"][i]["index"].as_u64().unwrap() as usize}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(plan:&mut PositionalChain){plan.begin_close();for _ in 0..100000{if plan.terminal_is_empty(){return}let d=plan.close_demand();assert_eq!(plan.close_step(Default::default()).unwrap(),Default::default());plan.close_step(grant(d)).unwrap();}panic!("positional prefix close stalled")}
#[test]
fn repeated_positional_prefixes_keep_source_and_original_authority(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let s=Source(row);let mut plan=PositionalChain::new();let mut turns=0usize;loop{let d=plan.demand(&s).unwrap();for axis in 0..5{let mut short=grant(d);match axis{0=>short.maximum_items=0,1=>short.maximum_copy_bytes=d.copy_bytes-1,2=>{if d.capacity_bytes==0{continue}short.maximum_capacity_bytes=d.capacity_bytes-1},3=>{if d.release_bytes==0{continue}short.maximum_release_bytes=d.release_bytes-1},_=>short.maximum_depth=d.depth-1}assert_eq!(plan.advance(&s,short).unwrap().progress,Default::default())}let step=plan.advance(&s,grant(d)).unwrap();turns+=1;assert!(turns<100000);if let Some(error)=step.error{assert_eq!(error,row["error"].as_str().unwrap());break}if step.done{assert!(row.get("error").is_none());let expected:Vec<_>=row["origins"].as_array().unwrap().iter().map(|row|Address{step:row[0].as_u64().map(|v|v as usize),row:row[1].as_u64().unwrap() as usize}).collect();assert_eq!(plan.origins().unwrap(),expected.as_slice());break}}close(&mut plan);for cut in[0,1,7,turns.saturating_sub(1)]{let mut plan=PositionalChain::new();for _ in 0..cut{let d=plan.demand(&s).unwrap();let step=plan.advance(&s,grant(d)).unwrap();if step.done||step.error.is_some(){break}}close(&mut plan)}}}
